function renderDiaries(filter='전체'){['#home-diaries','#all-diaries','#profile-diaries'].forEach(target=>{const root=$(target);root.replaceChildren();let list=target==='#all-diaries'?diaries.filter(d=>filter==='전체'||d.subtitle===filter):diaries.slice(0,3);list.forEach(d=>{const card=el('button','diary-card'),cover=el('div','cover'),img=el('img');img.src=d.items?.find(i=>i.type==='photo')?.content||photos[d.image]||photos.lake;img.alt=d.title;cover.append(img,el('span','cover-label',d.title),el('span','cover-spark','✧'));card.append(cover,el('h3','',target==='#home-diaries'?(d.subtitle||d.title):d.title),el('p','',d.date+' · '+(d.subtitle||'나의 기록')));card.onclick=()=>openEditor(d);root.append(card)});if(target!=='#profile-diaries'){const add=el('button','blank');add.setAttribute('aria-label','새 다이어리 만들기');add.append(el('b','','＋'),el('span','','새로운 기록'));add.onclick=()=>openEditor();root.append(add)}});$('#diary-total').textContent=diaries.length;$('#profile-count').textContent=diaries.length}
