function renderTemplates(root,list){$(root).replaceChildren();list.forEach(t=>{const idx=templates.indexOf(t),card=el('button','template-card'),preview=el('div','template-preview'),paper=el('div','mini-page');preview.style.background=t[3];paper.style.transform=`rotate(${idx%2?2:-2}deg)`;paper.append(el('h4','',t[0]));const img=el('img');img.src=photos[t[2]];img.alt=t[0];img.loading='lazy';paper.append(img,art(t[4],'decoration'),el('p','',t[1]==='플래너'?'□ 산책하기\n□ 오늘의 행복 기록하기\n□ 나에게 다정하기':'오늘은 정말 행복한 하루였다!\n좋아하는 순간들을 모아\n오래 기억하고 싶어 ♡'));const img2=img.cloneNode();img2.className='second-photo';img2.src=idx%2?photos.lake:photos.flowers;paper.append(img2,art(idx%2?0:6,'page-art'));preview.append(paper);card.append(preview,el('h3','',t[0]));card.onclick=()=>openEditor(null,idx);$(root).append(card)});if(!list.length)$(root).append(el('p','storage-note','검색 결과가 없어요. 다른 단어로 찾아보세요.'))}
let templateCategory='전체';function filterTemplates(){const q=$('#template-search').value.trim();renderTemplates('#all-templates',templates.filter(t=>(templateCategory==='전체'||t[1]===templateCategory)&&(!q||(t[0]+t[1]).includes(q))))}$$('#home-chips button').forEach(b=>b.onclick=()=>{templateCategory=b.textContent;$$('#home-chips button').forEach(c=>c.classList.toggle('selected',b===c));filterTemplates()});$('#template-search').oninput=filterTemplates;
