function defaultItems(i){const t=templates[i];return[{type:'photo',content:photos[t[2]],x:45,y:33,w:300,h:330},{type:'text',content:t[1]==='플래너'?'오늘 나를 위한 작은 약속\n□ 좋아하는 음악 듣기\n□ 산책하며 하늘 보기\n□ 소중한 순간 남기기':'오늘은 정말 행복한 하루였다!\n오랜만에 친구들이랑 맛있는 것도 먹고\n예쁜 카페도 가고…\n역시 행복은 소소한 것들에 있나봐. ♡',x:45,y:395},{type:'sticker',sprite:4,content:'데이지',x:414,y:62},{type:'sticker',sprite:2,content:'반짝 별',x:352,y:22},{type:'sticker',sprite:0,content:'고양이',x:464,y:235},{type:'sticker',sprite:15,content:'체크 리본',x:430,y:162},{type:'photo',content:photos.flowers,x:47,y:710,w:215,h:220},{type:'photo',content:photos.lake,x:283,y:685,w:255,h:240},{type:'sticker',sprite:6,content:'튤립',x:13,y:610},{type:'text',content:'my little happy day',x:150,y:635},{type:'sticker',sprite:t[4],content:'장식',x:491,y:884}]}
function resizePaper(){const w=$('.paper-area').clientWidth-36;if(w<=0)return;scale=Math.min(1,w/600);$('#paper').style.transform=`scale(${scale})`;$('.paper-frame').style.width=600*scale+'px';$('.paper-frame').style.height=1000*scale+'px'}window.addEventListener('resize',resizePaper);
function openEditor(d=null,i=0){current=d?JSON.parse(JSON.stringify(d)):{id:crypto.randomUUID(),title:new Date().toLocaleDateString('ko-KR')+' 오늘의 기록',date:new Date().toLocaleDateString('sv-SE').replaceAll('-','.'),image:templates[i][2],template:i,subtitle:templates[i][1]==='여행'?'여행':'일상'};$('#title-input').value=current.title;$('#paper').replaceChildren();$('#paper').style.backgroundColor=current.background||'#fffdf7';$('#paper-color').value=current.background||'#fffdf7';(current.items||defaultItems(current.template||0)).forEach(addPiece);selected=null;dirty=false;$('#editor').classList.remove('hidden');$('#editor-drawer').classList.add('hidden');document.body.style.overflow='hidden';document.querySelector(".app").inert=true;resizePaper();}
function addPiece(data){const p=el('div','piece '+data.type);p.dataset.type=data.type;p.style.left=data.x+'px';p.style.top=data.y+'px';if(data.type==='photo'){const img=el('img');img.src=data.content;img.alt='다이어리 사진';p.append(img);p.style.width=(data.w||220)+'px';p.style.height=(data.h||190)+'px'}else if(data.type==='sticker'){const n=Number.isInteger(data.sprite)?data.sprite:2;p.dataset.sprite=n;p.setAttribute('aria-label',data.content||stickers[n][0]);p.style.backgroundPosition=`${(n%4)*100/3}% ${Math.floor(n/4)*100/3}%`}else p.textContent=data.content;
p.onpointerdown=e=>{if(p.isContentEditable)return;$$('.piece').forEach(x=>x.classList.remove('selected'));p.classList.add('selected');selected=p;const box=p.getBoundingClientRect();if(data.type==='photo'&&e.clientX>box.right-18&&e.clientY>box.bottom-18){dirty=true;return}e.preventDefault();p.setPointerCapture(e.pointerId);const x=e.clientX,y=e.clientY,left=p.offsetLeft,top=p.offsetTop;p.onpointermove=ev=>{p.style.left=Math.max(0,Math.min(600-p.offsetWidth,left+(ev.clientX-x)/scale))+'px';p.style.top=Math.max(0,Math.min(1000-p.offsetHeight,top+(ev.clientY-y)/scale))+'px';dirty=true};p.onpointerup=p.onpointercancel=()=>{p.onpointermove=null}};
if(data.type==='text'){p.ondblclick=()=>{p.contentEditable='true';p.focus()};p.onblur=()=>{p.contentEditable='false';dirty=true};p.oninput=()=>dirty=true;p.onpaste=e=>{e.preventDefault();const sel=window.getSelection();if(sel.rangeCount){const r=sel.getRangeAt(0);r.deleteContents();r.insertNode(document.createTextNode(e.clipboardData.getData('text/plain')));sel.collapseToEnd()}}}$('#paper').append(p);dirty=true;}
function capture(){return{...current,title:$('#title-input').value.trim()||'이름 없는 하루',background:$('#paper-color').value,items:$$('#paper .piece').map(p=>({type:p.dataset.type,content:p.dataset.type==='photo'?p.querySelector('img').getAttribute('src'):p.dataset.type==='sticker'?p.getAttribute('aria-label'):p.innerText,sprite:p.dataset.sprite===undefined?undefined:Number(p.dataset.sprite),x:p.offsetLeft,y:p.offsetTop,w:p.offsetWidth,h:p.offsetHeight}))}}
function save(){const d=capture(),next=diaries.some(x=>x.id===d.id)?diaries.map(x=>x.id===d.id?d:x):[d,...diaries];try{localStorage.setItem('diaru-diaries-v1',JSON.stringify(next));diaries=next;current=d;dirty=false;renderDiaries();toast('오늘의 기록을 저장했어요 ♡')}catch{toast('저장 공간이 부족해요. 공유 파일로 먼저 보관해주세요.')}}
