$('#photo-input').onchange=e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('이미지 파일을 선택해주세요.');return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),r=Math.min(1,1100/img.width,1100/img.height);c.width=img.width*r;c.height=img.height*r;c.getContext('2d').drawImage(img,0,0,c.width,c.height);addPiece({type:'photo',content:c.toDataURL('image/jpeg',.82),x:150,y:200,w:250,h:260});toast('사진을 추가했어요.')};img.onerror=()=>toast('JPG 또는 PNG 사진으로 다시 시도해주세요.');img.src=reader.result};reader.readAsDataURL(file);e.target.value=''};$('#delete-item').onclick=()=>{if(selected){selected.remove();selected=null;dirty=true}else toast('삭제할 조각을 먼저 눌러주세요.')};
async function asData(src){if(src.startsWith('data:'))return src;const response=await fetch(src);if(!response.ok)throw Error('image');const blob=await response.blob();return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)})}
$('#export').onclick=async()=>{const button=$('#export');button.disabled=true;toast('공유 파일을 만들고 있어요.');try{const clone=$('#paper').cloneNode(true);clone.style.transform='none';clone.querySelectorAll('.piece').forEach(p=>{p.classList.remove('selected');p.removeAttribute('contenteditable')});const sprite=await asData('assets/stickers.png');await Promise.all([...clone.querySelectorAll('img')].map(async img=>{img.src=await asData(img.getAttribute('src'))}));const title=el('title','',capture().title);const html='<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+title.outerHTML+'<style>body{margin:20px;background:#eef0f4;display:grid;place-items:center}#paper{position:relative;width:600px;height:1000px;overflow:hidden;background-image:linear-gradient(#8799ae18 1px,transparent 1px),linear-gradient(90deg,#8799ae18 1px,transparent 1px);background-size:22px 22px}.piece{position:absolute;white-space:pre-wrap;box-sizing:border-box}.text{font-family:cursive;font-size:27px;line-height:1.55;padding:4px;max-width:540px}.sticker{width:85px;height:85px;background-size:400% 400%;background-image:url('+sprite+');mix-blend-mode:multiply}.photo{padding:8px 8px 23px;background:white;box-shadow:0 3px 8px #0002}.photo img{width:100%;height:100%;object-fit:cover}</style>'+clone.outerHTML+'</html>';const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=el('a');a.href=url;a.download=capture().title.replace(/[<>:"/\\|?*]/g,'')+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('공유 파일을 저장했어요. 친구에게 보내보세요!')}catch{toast('사진을 불러오지 못했어요. 연결을 확인하고 다시 시도해주세요.')}finally{button.disabled=false}};$('#share-tool').onclick=()=>$('#export').click();$('#profile-edit').onclick=()=>{const name=prompt('프로필 이름을 적어주세요.',$('.profile-detail h1').textContent);if(name?.trim()){const text=name.trim().slice(0,40);$('.profile-detail h1').textContent=text;try{localStorage.setItem('diaru-profile-name',text)}catch{}}};try{const name=localStorage.getItem('diaru-profile-name');if(name)$('.profile-detail h1').textContent=name}catch{}
